class SoundScriptManager {
public:
    enum EventType { SS_FE_ONX = 24 };
    void pause();
    void unpause();
    void playEvent(EventType type, void *ent = 0, float arg = 0.0f);
};

struct FEManager { char padding[0x15678]; bool fe_done; };
extern FEManager frontendmanager;
extern SoundScriptManager *sound_script_manager;

class KeyboardMenu {
    char padding0[0x4c];
    FEMenuEntry *highlighted;
    FEMenuSystem *system;
    char padding1[0x1b8];
    SaveLoadFrontEnd *sl_parent;
public:
