};

__asm__(".equ frontendmanager, 0x003F7728");
__asm__(".equ sound_script_manager, 0x0045B4A0");
__asm__(".equ KeyOn__12KeyboardMenuib, 0x001A28B8");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ SetDState__16SaveLoadFrontEndibT2, 0x0019B760");

void KeyboardMenu::go_to_previous_menu()
{
    if (highlighted->entry_num < 37)
        KeyOn(highlighted->entry_num, false);

    if (frontendmanager.fe_done)
        sound_script_manager->unpause();
    sound_script_manager->playEvent(SoundScriptManager::SS_FE_ONX);
    if (frontendmanager.fe_done)
        sound_script_manager->pause();

    if (frontendmanager.fe_done)
        sl_parent->SetDState(7);
    else
    {
        if (sl_parent->back_menu == -1)
            sl_parent->SetDState(7);
        else if (sl_parent->back_sub_menu == -1)
        {
            FEMenuSystemVTable *table = system->vtable;
            table->MakeActive((char *)system + table->adjustment,
                              sl_parent->back_menu, 1);
        }
        else
        {
            FEMenuSystemVTable *table = system->vtable;
            table->MakeActive((char *)system + table->adjustment,
                              sl_parent->back_menu,
                              sl_parent->back_sub_menu);
        }
    }
}
